import { readFileSync } from 'fs';

interface Config {
  litellmUrl: string;
  models: string[];
  timeout: number;
}

export function loadConfig(path: string): Config {
  const raw = readFileSync(path, 'utf-8');
  const parsed = JSON.parse(raw);
  return {
    litellmUrl: parsed.litellm_url,
    models: parsed.models,
    timeout: parsed.timeout,
  };
}

export async function fetchModels(config: Config): Promise<string[]> {
  const response = await fetch(`${config.litellmUrl}/models`);
  const data = await response.json();
  return data.data.map((m: any) => m.id);
}

export async function runBenchmark(configPath: string) {
  const config = loadConfig(configPath);
  const models = await fetchModels(config);
  console.log(`Running benchmark with ${models.length} models`);
  // ... benchmark logic
}
